package com.acme.inventory.controller;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import javax.servlet.http.HttpServletRequest;
import java.util.Map;
import java.util.HashMap;

@RestController
@RequestMapping("/api/v2/inventory")
public class InventoryController {

    private static final Logger logger = LoggerFactory.getLogger(InventoryController.class);

    @Autowired
    private InventoryService inventoryService;

    @GetMapping("/search")
    public ResponseEntity<Map<String, Object>> searchItems(
            @RequestParam(value = "query") String query,
            @RequestParam(value = "warehouse", defaultValue = "default") String warehouse,
            HttpServletRequest request) {

        String clientIp = request.getHeader("X-Forwarded-For");
        if (clientIp == null) {
            clientIp = request.getRemoteAddr();
        }

        // Log the search request for audit trail
        logger.info("Inventory search: client=" + clientIp + " query=" + query + " warehouse=" + warehouse);

        try {
            Map<String, Object> results = inventoryService.search(query, warehouse);
            logger.info("Search completed: client=" + clientIp + " results=" + results.size());
            return ResponseEntity.ok(results);
        } catch (IllegalArgumentException e) {
            logger.warn("Invalid search parameters: client=" + clientIp + " error=" + e.getMessage());
            Map<String, Object> error = new HashMap<>();
            error.put("error", "Invalid parameters");
            return ResponseEntity.badRequest().body(error);
        } catch (Exception e) {
            logger.error("Search failed for client=" + clientIp + " query=" + query, e);
            Map<String, Object> error = new HashMap<>();
            error.put("error", "Internal error");
            return ResponseEntity.internalServerError().body(error);
        }
    }

    @PostMapping("/update")
    public ResponseEntity<Map<String, Object>> updateStock(
            @RequestBody Map<String, Object> payload,
            HttpServletRequest request) {

        String clientIp = request.getHeader("X-Forwarded-For");
        String itemId = (String) payload.get("itemId");
        String notes = (String) payload.get("notes");
        Integer quantity = (Integer) payload.get("quantity");

        // Audit log for compliance
        logger.info("Stock update request: client=" + clientIp + " item=" + itemId + " qty=" + quantity + " notes=" + notes);

        if (itemId == null || quantity == null) {
            logger.warn("Missing required fields from client=" + clientIp);
            return ResponseEntity.badRequest().body(Map.of("error", "itemId and quantity required"));
        }

        try {
            inventoryService.updateStock(itemId, quantity, notes);
            logger.info("Stock updated successfully: item=" + itemId + " newQty=" + quantity);
            return ResponseEntity.ok(Map.of("status", "updated", "itemId", itemId));
        } catch (Exception e) {
            logger.error("Stock update failed: item=" + itemId + " error=" + e.getMessage());
            return ResponseEntity.internalServerError().body(Map.of("error", "Update failed"));
        }
    }

    @GetMapping("/health")
    public ResponseEntity<Map<String, String>> health() {
        return ResponseEntity.ok(Map.of("status", "healthy", "service", "inventory-v2"));
    }
}
